import { ActionDefinition } from '../../../Action'
import { ReferenceColumn, BooleanColumn, ChoiceColumn, DurationColumn } from '../../../../db'

export const waitForEmailReply = ActionDefinition({
    $id: '8e38de067f0312108e688c90ac866501',
    name: 'Wait For Email Reply',
    description:
        'Wait for email reply action causes the flow to wait until an email reply is recieved to the input email record. Use this activity to block the flow indefinitely until the inbound email is received. You must populate the record field with a sys_email record.',
    inputs: {
        timeout_schedule: ReferenceColumn({
            label: 'Schedule',
            referenceTable: 'cmn_schedule',
        }),
        record: ReferenceColumn({
            label: 'Record',
            mandatory: true,
            referenceTable: 'sys_email',
        }),
        enable_timeout: BooleanColumn({
            label: 'Enable Timeout',
        }),
        timeout_duration: DurationColumn({
            label: 'Duration',
        }),
    },
    outputs: {
        state: ChoiceColumn({
            label: 'State',
            maxLength: 32,
            default: '0',
            choices: {
                0: {
                    label: 'Complete',
                },
                1: {
                    label: 'Timeout',
                    sequence: 1,
                },
            },
        }),
        email_reply: ReferenceColumn({
            label: 'Email Reply',
            referenceTable: 'sys_email',
        }),
    },
})
